#include <iostream>
#include <cstring>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1 << 29;
const int MAXN = 500;

struct Edge {
    int to, rev, cap, flow;
    Edge(int to = 0, int rev = 0, int cap = 0, int flow = 0)
        : to(to), rev(rev), cap(cap), flow(flow) {}
};

vector<Edge> graph[MAXN];
int level[MAXN], it[MAXN];
int n, t, sx, sy;
int temp[11][11];
bool pass[11][11];

void add_edge(int a, int b, int cap) {
    graph[a].push_back(Edge(b, (int)graph[b].size(), cap, 0));
    graph[b].push_back(Edge(a, (int)graph[a].size() - 1, 0, 0));
}

bool bfs() {
    queue<int> q;
    q.push(0);
    memset(level, -1, (n * n * 2 + 2) * sizeof(level[0]));
    level[0] = 0;
    while (!q.empty() && level[n * n * 2 + 1] == -1) {
        int v = q.front();
        q.pop();
        for (size_t i = 0; i < graph[v].size(); ++i) {
            Edge const &ed = graph[v][i];
            if (level[ed.to] == -1 && ed.flow < ed.cap) {
                level[ed.to] = level[v] + 1;
                q.push(ed.to);
            }
        }
    }
    return level[n * n * 2 + 1] != -1;
}

int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v == n * n * 2 + 1) return flow;
    for (int &i = it[v]; i < (int)graph[v].size(); ++i) {
        Edge &ed = graph[v][i];
        if (level[ed.to] != level[v] + 1) continue;
        int pushed = dfs(ed.to, min(flow, ed.cap - ed.flow));
        if (pushed) {
            ed.flow += pushed;
            graph[ed.to][ed.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (bfs()) {
        memset(it, 0, (n * n * 2 + 2) * sizeof(it[0]));
        while (int pushed = dfs(0, INF))
            flow += pushed;
    }
    return flow;
}

int way(int x1, int y1, int x2, int y2) {
    queue<pair<int, pair<int, int> > > q;
    q.push(make_pair(0, make_pair(x1, y1)));
    int h[11][11];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            h[i][j] = INF;

    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        h[x][y] = v;

        if (x > 0 && pass[x - 1][y] && h[x - 1][y] > v + 1) {
            bool target = (x - 1 == x2 && y == y2);
            int lim = temp[x - 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x - 1, y)));
        }
        if (y > 0 && pass[x][y - 1] && h[x][y - 1] > v + 1) {
            bool target = (x == x2 && y - 1 == y2);
            int lim = temp[x][y - 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y - 1)));
        }
        if (x < n - 1 && pass[x + 1][y] && h[x + 1][y] > v + 1) {
            bool target = (x + 1 == x2 && y == y2);
            int lim = temp[x + 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x + 1, y)));
        }
        if (y < n - 1 && pass[x][y + 1] && h[x][y + 1] > v + 1) {
            bool target = (x == x2 && y + 1 == y2);
            int lim = temp[x][y + 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y + 1)));
        }
    }
    return h[x2][y2];
}

int main() {
    cin >> n >> t;
    queue<pair<int, pair<int, int> > > q;
    char ch;
    int k = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            temp[i][j] = t;
            if (ch == 'Z') {
                sx = i;
                sy = j;
                pass[i][j] = false;
            } else if (ch == 'Y') {
                pass[i][j] = false;
            } else {
                pass[i][j] = true;
            }
            add_edge(0, k++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    k = n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            add_edge(k++, n * n * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    q.push(make_pair(0, make_pair(sx, sy)));
    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        temp[x][y] = v;
        if (x > 0 && v + 1 < temp[x - 1][y] && pass[x - 1][y])
            q.push(make_pair(v + 1, make_pair(x - 1, y)));
        if (y > 0 && v + 1 < temp[x][y - 1] && pass[x][y - 1])
            q.push(make_pair(v + 1, make_pair(x, y - 1)));
        if (x < n - 1 && v + 1 < temp[x + 1][y] && pass[x + 1][y])
            q.push(make_pair(v + 1, make_pair(x + 1, y)));
        if (y < n - 1 && v + 1 < temp[x][y + 1] && pass[x][y + 1])
            q.push(make_pair(v + 1, make_pair(x, y + 1)));
    }

    k = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int k1 = n * n;
            ++k;
            for (int z = 0; z < n; ++z) {
                for (int w = 0; w < n; ++w) {
                    ++k1;
                    if (pass[i][j] && pass[z][w] && way(i, j, z, w) <= t)
                        add_edge(k, k1, INF);
                }
            }
        }
    }

    cout << max_flow();
    return 0;
}
